package gb28181

import (
	"bytes"
	"cmp"
	"context"
	"errors"
	"fmt"
	"io"
	"slices"
	"time"

	"github.com/asticode/go-astits"
)

const mediaClock = 90000

// readMediaTS consumes the internal MPEG-TS stream generated by FFmpeg. Its
// first two PIDs hold the Annex B video and optional raw G.711 PES payloads.
func readMediaTS(ctx context.Context, input io.Reader, videoCodec string, audio bool, send func(mediaUnit) error) error {
	demuxer := astits.NewDemuxer(ctx, input, astits.DemuxerOptPacketSize(188))
	var pending []mediaUnit
	var pendingBytes int
	var highDTS, videoDTS, audioDTS int64
	var started, gotVideo, gotAudio bool
	for {
		packet, err := demuxer.NextData()
		if errors.Is(err, astits.ErrNoMorePackets) {
			for _, unit := range pending {
				if err := send(unit); err != nil {
					return err
				}
			}
			return io.EOF
		}
		if err != nil {
			return fmt.Errorf("读取 FFmpeg 90 kHz 媒体时钟失败：%w", err)
		}
		if packet.PES == nil || len(packet.PES.Data) == 0 || packet.PID != 256 && packet.PID != 257 {
			continue
		}
		header := packet.PES.Header.OptionalHeader
		if header == nil || header.PTS == nil {
			return errors.New("本地媒体 PES 缺少 PTS")
		}
		rawDTS := header.PTS.Base
		if header.DTS != nil {
			rawDTS = header.DTS.Base
		}
		if !started {
			started = true
			highDTS = rawDTS
		}
		dts := unwrapMediaClock(rawDTS, highDTS)
		highDTS = max(highDTS, dts)
		unit := mediaUnit{data: packet.PES.Data, dts: dts, pts: unwrapMediaClock(header.PTS.Base, dts), stream: videoStreamID}
		if packet.PID == 256 {
			unit.key = containsRandomAccess(unit.data, videoCodec)
			gotVideo, videoDTS = true, dts
		} else {
			unit.stream = audioStreamID
			gotAudio, audioDTS = true, dts
		}
		if !audio {
			if err := send(unit); err != nil {
				return err
			}
			continue
		}
		pending = append(pending, unit)
		pendingBytes += len(unit.data)
		slices.SortStableFunc(pending, func(a, b mediaUnit) int { return cmp.Compare(a.dts, b.dts) })
		for len(pending) > 0 {
			next := pending[0]
			bothTracksReady := gotAudio && gotVideo && next.dts <= min(videoDTS, audioDTS)
			// A sparse track may not contribute for a long time. Bound the
			// lookahead by media time, bytes and count before pacing frames.
			if !bothTracksReady && highDTS-next.dts < mediaClock && pendingBytes < 8<<20 && len(pending) < 128 {
				break
			}
			if err := send(next); err != nil {
				return err
			}
			pendingBytes -= len(next.data)
			pending = slices.Delete(pending, 0, 1)
		}
	}
}

func unwrapMediaClock(raw, around int64) int64 {
	const cycle int64 = 1 << 33
	diff := (raw-around+cycle/2)&(cycle-1) - cycle/2
	return around + diff
}

func containsRandomAccess(data []byte, videoCodec string) bool {
	start := []byte{0, 0, 1}
	for len(data) > 3 {
		i := bytes.Index(data, start)
		if i < 0 || i+3 >= len(data) {
			return false
		}
		data = data[i+3:]
		if videoCodec == "hevc" {
			kind := (data[0] >> 1) & 63
			if kind >= 16 && kind <= 23 {
				return true
			}
		} else if data[0]&31 == 5 {
			return true
		}
	}
	return false
}

func clockDuration(ticks int64) time.Duration {
	return time.Duration(ticks/mediaClock)*time.Second + time.Duration(ticks%mediaClock)*time.Second/mediaClock
}

func paceMedia(ctx context.Context, speed float64, send func(mediaUnit) error) func(mediaUnit) error {
	var start time.Time
	var origin int64
	return func(unit mediaUnit) error {
		if start.IsZero() {
			start, origin = time.Now(), unit.dts
		}
		delay := time.Duration(float64(clockDuration(unit.dts-origin))/speed) - time.Since(start)
		if delay > 0 {
			timer := time.NewTimer(delay)
			defer timer.Stop()
			select {
			case <-timer.C:
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		return send(unit)
	}
}
